sed -i 's/var modelName by remember { mutableStateOf("") }/var modelName by remember { mutableStateOf("") }\n        var providerType by remember { mutableStateOf("OpenAI Compatible") }\n        var typeDropdownExpanded by remember { mutableStateOf(false) }\n        val types = listOf("OpenAI Compatible", "Anthropic Compatible", "Gemini Compatible")/' app/src/main/java/com/example/ui/screens/SettingsScreen.kt

sed -i '/OutlinedTextField(/i \                    Box(modifier = Modifier.fillMaxWidth()) {\n                        OutlinedTextField(\n                            value = providerType,\n                            onValueChange = {},\n                            readOnly = true,\n                            label = { Text("Provider Type") },\n                            trailingIcon = { Icon(Icons.Default.KeyboardArrowDown, contentDescription = null) },\n                            modifier = Modifier.fillMaxWidth()\n                        )\n                        androidx.compose.material3.Surface(\n                            modifier = Modifier.matchParentSize().clickable { typeDropdownExpanded = true },\n                            color = androidx.compose.ui.graphics.Color.Transparent\n                        ) {}\n                        DropdownMenu(\n                            expanded = typeDropdownExpanded,\n                            onDismissRequest = { typeDropdownExpanded = false }\n                        ) {\n                            types.forEach { type ->\n                                DropdownMenuItem(\n                                    text = { Text(type) },\n                                    onClick = {\n                                        providerType = type\n                                        typeDropdownExpanded = false\n                                    }\n                                )\n                            }\n                        }\n                    }\n' app/src/main/java/com/example/ui/screens/SettingsScreen.kt

sed -i 's/viewModel.addCustomProvider(name, baseUrl, apiKey, modelName)/viewModel.addCustomProvider(name, baseUrl, apiKey, modelName, providerType)/' app/src/main/java/com/example/ui/screens/SettingsScreen.kt
